"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[8637],{2964(e){e.exports=JSON.parse('{"tag":{"label":"Recursion","permalink":"/concepts/tags/recursion","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"algorithm-design-paradigms/divide-and-conquer","title":"Divide and Conquer","description":"The Divide and Conquer (D&C) paradigm represents one of the most powerful systemic strategies in algorithm design. Instead of attacking a complex computational problem globally, this approach structurally breaks down problem instances into smaller, homogeneous variants. It fundamentally shifts execution from complex global management to localized resolution and structural combination.","permalink":"/concepts/algorithm-design-paradigms/divide-and-conquer"},{"id":"fundamental-problem-domains/quicksort","title":"Quicksort","description":"Quicksort, invented by Tony Hoare around 1960, is one of the most important algorithms ever designed. It is the basis of the sorting routines of many programming languages and libraries, and it is usually the fastest general-purpose sorting algorithm in practice. It improves the idea of exchange: instead of exchanging adjacent elements, it exchanges elements that are far apart, removing many inversions at once.","permalink":"/concepts/fundamental-problem-domains/quicksort"}],"unlisted":false}}')}}]);